// script.js — Application entry point & initialization
// Depends on: utils.js, translation.js, confessions.js

// --- DARK MODE: Permanently locked ---
// --- LEGACY TAB ROUTER MAPPING ---
const tabToPageMap = {
    "calendar-tab": "calendar.html",
    "bus-tab": "bus.html",
    "library-tab": "library.html",
    "health-tab": "health.html",
    "gpa-tab": "gpa.html",
    "scholarships-tab": "scholarships.html",
    "exams-tab": "exams.html",
    "links-tab": "wifi.html",
    "support-tab": "support.html",
    "activities-tab": "activities.html",
    "marketplace-tab": "marketplace.html",
    "updates-tab": "updates.html"
};

// Check and handle hash redirect on load and hash change
function handleHashRedirect() {
    if (window.location.hash) {
        const hashId = window.location.hash.replace('#', '');
        if (tabToPageMap[hashId]) {
            window.location.href = tabToPageMap[hashId];
            return true;
        }
    }
    return false;
}

// Run hash redirect check immediately
handleHashRedirect();
window.addEventListener("hashchange", handleHashRedirect);


// --- TAB NAVIGATION SYSTEM ---
const navItems = document.querySelectorAll(".nav-item");
const mobileNavBtns = document.querySelectorAll(".mobile-nav-btn[data-tab]");
const drawerItemBtns = document.querySelectorAll(".drawer-item-btn[data-tab]");
const tabContents = document.querySelectorAll(".tab-content");

function switchTab(tabId) {
    if (!tabId) return;

    // If tab corresponds to a standalone page, redirect immediately
    if (tabToPageMap[tabId]) {
        window.location.href = tabToPageMap[tabId];
        return;
    }

    // If target tab panel doesn't exist on this page, redirect to index.html
    const targetPanel = document.getElementById(tabId);
    if (!targetPanel) {
        window.location.href = "index.html";
        return;
    }

    navItems.forEach(item => {
        item.classList.toggle("active", item.getAttribute("data-tab") === tabId);
    });
    mobileNavBtns.forEach(btn => {
        btn.classList.toggle("active", btn.getAttribute("data-tab") === tabId);
    });
    drawerItemBtns.forEach(btn => {
        btn.classList.toggle("active", btn.getAttribute("data-tab") === tabId);
    });
    tabContents.forEach(panel => {
        const isActive = panel.id === tabId;
        panel.classList.toggle("active", isActive);

        // Lazy-load ads if the panel becomes active
        if (isActive && window.initAdsInContainer) {
            setTimeout(() => {
                window.initAdsInContainer(panel);
            }, 50);
        }
    });
    closeMobileDrawer();
    window.scrollTo({ top: 0, behavior: 'instant' });
}

navItems.forEach(item => {
    item.addEventListener("click", () => switchTab(item.getAttribute("data-tab")));
});

mobileNavBtns.forEach(btn => {
    btn.addEventListener("click", () => switchTab(btn.getAttribute("data-tab")));
});

drawerItemBtns.forEach(btn => {
    btn.addEventListener("click", () => switchTab(btn.getAttribute("data-tab")));
});

// --- MOBILE "MORE" DRAWER CONTROLLER ---
const openDrawerBtn = document.getElementById("openMobileDrawerBtn");
const closeDrawerBtn = document.getElementById("closeMobileDrawerBtn");
const drawerOverlay = document.getElementById("mobileMoreDrawer");

function openMobileDrawer() {
    if (drawerOverlay) drawerOverlay.classList.add("active");
}

function closeMobileDrawer() {
    if (drawerOverlay) drawerOverlay.classList.remove("active");
}

if (openDrawerBtn) openDrawerBtn.addEventListener("click", openMobileDrawer);
if (closeDrawerBtn) closeDrawerBtn.addEventListener("click", closeMobileDrawer);
if (drawerOverlay) {
    drawerOverlay.addEventListener("click", (e) => {
        if (e.target === drawerOverlay) closeMobileDrawer();
    });
}


// --- INITIALIZATION ---
document.addEventListener("DOMContentLoaded", () => {
    // Apply saved language
    setLanguage(currentLang);
    if (typeof syncStructuredTableLabels === 'function') syncStructuredTableLabels();

    // Bind language toggle buttons
    const desktopToggle = document.getElementById("desktopLangToggle");
    const mobileToggle = document.getElementById("mobileLangToggle");
    const drawerToggle = document.getElementById("drawerLangToggle");
    const handleToggle = () => {
        toggleLanguage();
        if (typeof syncStructuredTableLabels === 'function') syncStructuredTableLabels();
    };
    if (desktopToggle) desktopToggle.addEventListener("click", handleToggle);
    if (mobileToggle) mobileToggle.addEventListener("click", handleToggle);
    if (drawerToggle) drawerToggle.addEventListener("click", handleToggle);

    // Dynamic Time-Based Greeting for Campus Hero Banner
    function updateHeroGreeting(lang) {
        const heroGreetingTitle = document.getElementById("heroGreetingTitle");
        const heroTimeIcon = document.getElementById("heroTimeIcon");
        const heroGreetingSubtitle = document.getElementById("heroGreetingSubtitle");
        const weatherBadge = document.getElementById("weatherLiveBadge");
        if (!heroGreetingTitle) return;

        const currentLanguage = lang || (typeof currentLang !== 'undefined' ? currentLang : localStorage.getItem("lang")) || "en";
        const hour = new Date().getHours();
        let timeKey = "evening";
        let icon = "🌆";

        if (hour >= 5 && hour < 12) {
            timeKey = "morning";
            icon = "🌅";
        } else if (hour >= 12 && hour < 17) {
            timeKey = "afternoon";
            icon = "☀️";
        } else if (hour >= 17 && hour < 21) {
            timeKey = "evening";
            icon = "🌆";
        } else {
            timeKey = "night";
            icon = "🌙";
        }

        if (heroTimeIcon) heroTimeIcon.textContent = icon;

        const greetings = {
            en: {
                morning: "Good Morning, UTeMians",
                afternoon: "Good Afternoon, UTeMians",
                evening: "Good Evening, UTeMians",
                night: "Late Night at Campus?",
                subtitle: "Your safe, 100% anonymous space for campus confessions, rants & peer stories.",
                weather_badge: "Live Weather"
            },
            ms: {
                morning: "Selamat Pagi, Warga UTeM",
                afternoon: "Selamat Tengah Hari, Warga UTeM",
                evening: "Selamat Petang, Warga UTeM",
                night: "Sesi Malam Kampus?",
                subtitle: "Ruang selamat & 100% tanpa nama untuk luahan, kehidupan kampus & suara mahasiswa.",
                weather_badge: "Cuaca Terkini"
            }
        };

        const dict = greetings[currentLanguage] || greetings.en;
        heroGreetingTitle.textContent = dict[timeKey];
        if (heroGreetingSubtitle) heroGreetingSubtitle.textContent = dict.subtitle;
        if (weatherBadge) weatherBadge.textContent = dict.weather_badge;
    }

    window.updateHeroGreeting = updateHeroGreeting;
    updateHeroGreeting(currentLang);

    // UTeM Live Campus Weather & Imminent Next Bus Ticker
    async function initCampusTicker() {
        const weatherPill = document.getElementById("campusWeatherPill");
        const tickerSlide = document.getElementById("tickerSlide");
        const weatherText = document.getElementById("weatherText");
        const weatherIcon = document.getElementById("weatherIcon");
        const weatherBadge = document.getElementById("weatherBadge");
        if (!weatherPill || !weatherText) return;

        let liveWeatherData = {
            icon: "⛅",
            text: "Durian Tunggal / Ayer Keroh: 31°C Fair",
            badge: (typeof currentLang !== 'undefined' && currentLang === 'ms') ? "Cuaca Terkini" : "Live Weather",
            badgeBg: "rgba(16, 185, 129, 0.15)",
            badgeColor: "#10b981"
        };

        try {
            const res = await fetch("https://api.open-meteo.com/v1/forecast?latitude=2.3138&longitude=102.3188&current_weather=true");
            if (res.ok) {
                const data = await res.json();
                if (data && data.current_weather) {
                    const temp = Math.round(data.current_weather.temperature);
                    const code = data.current_weather.weathercode;
                    const isDay = data.current_weather.is_day === 1;

                    let desc = isDay ? "Clear" : "Clear Night";
                    let icon = isDay ? "☀️" : "🌙";

                    if (code === 1) {
                        desc = isDay ? "Mainly Clear" : "Clear Night";
                        icon = isDay ? "🌤️" : "🌙";
                    } else if (code === 2) {
                        desc = "Partly Cloudy";
                        icon = isDay ? "⛅" : "☁️";
                    } else if (code === 3) {
                        desc = "Overcast";
                        icon = "☁️";
                    } else if (code === 45 || code === 48) {
                        desc = "Foggy / Hazy";
                        icon = "🌫️";
                    } else if ((code >= 51 && code <= 55) || code === 56 || code === 57) {
                        desc = "Drizzle";
                        icon = "🌦️";
                    } else if ((code >= 61 && code <= 67) || (code >= 80 && code <= 82)) {
                        desc = code >= 65 || code === 82 ? "Heavy Rain" : "Rain";
                        icon = "🌧️";
                    } else if (code >= 95 && code <= 99) {
                        desc = "Thunderstorm";
                        icon = "⛈️";
                    }

                    liveWeatherData = {
                        icon: icon,
                        text: `UTeM Campus: ${temp}°C ${desc}`,
                        badge: (typeof currentLang !== 'undefined' && currentLang === 'ms') ? "Cuaca Terkini" : "Live Weather",
                        badgeBg: "rgba(16, 185, 129, 0.15)",
                        badgeColor: "#10b981"
                    };

                    if (weatherIcon) weatherIcon.textContent = icon;
                    weatherText.textContent = liveWeatherData.text;
                }
            }
        } catch (err) {
            console.warn("Weather API fetch fallback:", err);
        }

        // Master Bus Schedules Dataset (synced with bus.js)
        const busSchedulesMaster = {
            special: {
                ki: {
                    monThu: ["07:30", "13:00", "13:30", "16:00", "17:30"],
                    friday: ["07:30", "13:00", "14:30", "17:00"],
                    weekend: []
                },
                kt: {
                    monThu: ["07:30", "13:00", "13:30", "17:00"],
                    friday: ["07:30", "13:00"],
                    weekend: []
                },
                ep: {
                    monThu: ["08:00", "13:00", "14:00", "17:30"],
                    friday: ["08:00", "12:30", "14:30", "17:30"],
                    weekend: []
                }
            },
            regular: {
                ftmk_regular: {
                    weekday: ["07:30","08:00","08:30","09:00","09:30","10:00","11:00","12:00","13:00","14:00","15:00","16:00","16:30","17:00","17:30","18:30","20:00"],
                    weekend: ["09:00","11:00","13:00","15:00","17:00","19:00","21:00"]
                },
                satria_regular: {
                    weekday: ["07:15","07:30","07:45","08:00","08:15","08:30","08:45","09:00","09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00","16:30","17:00","17:30","18:00","18:30","19:00","19:30","20:00","21:00","22:00"],
                    weekend: ["08:00","08:30","09:00","09:30","10:00","11:00","12:00","13:00","14:00","15:00","16:00","17:00","18:00","19:00","20:00","21:00","22:00"]
                },
                lestari_regular: {
                    weekday: ["07:20","07:40","08:00","08:20","08:40","09:00","09:20","09:40","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00","16:30","17:00","17:20","17:40","18:00","18:30","19:00","19:30","20:00","21:00"],
                    weekend: ["08:30","09:15","10:00","10:45","11:30","12:15","13:00","13:45","14:30","15:15","16:00","16:45","17:30","18:15","19:00","19:45","20:30"]
                }
            },
            m10a: {
                weekday: ["06:30","08:30","10:30","12:30","14:30","16:30","18:30","20:00"],
                weekend: ["07:30","09:30","11:30","13:30","15:30","17:30","19:30"]
            }
        };

        function getNextImminentBus() {
            const now = new Date();
            const nowMinutes = now.getHours() * 60 + now.getMinutes();
            const day = now.getDay(); // 0 = Sun, 1 = Mon, ..., 5 = Fri, 6 = Sat
            const isFriSatSun = (day === 0 || day === 5 || day === 6);

            // Nighttime blackout: If before 7:00 AM or after 10:00 PM (22:00), no buses running
            if (now.getHours() < 7 || now.getHours() >= 22) {
                return null;
            }

            let activeTab = null;
            let activeRoute = "ki";
            let activeSem = "special";
            try {
                activeTab = localStorage.getItem("ucpm_bus_active_tab");
                activeRoute = (localStorage.getItem("ucpm_active_bus_route") || "ki").toLowerCase();
                activeSem = localStorage.getItem("ucpm_bus_semester") || "special";
            } catch (e) {}

            const isMs = typeof currentLang !== 'undefined' && currentLang === 'ms';

            function getRouteDetails(routeKey, sem, d) {
                const isSatSun = (d === 0 || d === 6);
                const isFri = (d === 5);
                const key = ("" + routeKey).toLowerCase();

                if (key === "m10a") {
                    if (isFri || isSatSun) {
                        return { type: "m10a", name: "M10A", times: busSchedulesMaster.m10a.weekend };
                    } else {
                        return { type: "m10a", name: "M10A", times: [] };
                    }
                }

                if (sem === "regular") {
                    if (key === "satria" || key === "satria_regular") {
                        const times = isSatSun ? busSchedulesMaster.regular.satria_regular.weekend : busSchedulesMaster.regular.satria_regular.weekday;
                        return { type: "shuttle", name: "Satria", times: times };
                    }
                    if (key === "lestari" || key === "lestari_regular") {
                        const times = isSatSun ? busSchedulesMaster.regular.lestari_regular.weekend : busSchedulesMaster.regular.lestari_regular.weekday;
                        return { type: "shuttle", name: "Lestari", times: times };
                    }
                    const times = isSatSun ? busSchedulesMaster.regular.ftmk_regular.weekend : busSchedulesMaster.regular.ftmk_regular.weekday;
                    return { type: "shuttle", name: "KI", times: times };
                } else {
                    if (key === "kt") {
                        const times = isSatSun ? [] : (isFri ? busSchedulesMaster.special.kt.friday : busSchedulesMaster.special.kt.monThu);
                        return { type: "shuttle", name: "KT", times: times };
                    }
                    if (key === "ep") {
                        const times = isSatSun ? [] : (isFri ? busSchedulesMaster.special.ep.friday : busSchedulesMaster.special.ep.monThu);
                        return { type: "shuttle", name: "EP", times: times };
                    }
                    const times = isSatSun ? [] : (isFri ? busSchedulesMaster.special.ki.friday : busSchedulesMaster.special.ki.monThu);
                    return { type: "shuttle", name: "KI", times: times };
                }
            }

            function findNextDeparture(timesList, currentMins) {
                if (!timesList || !timesList.length) return null;
                for (const t of timesList) {
                    const [h, m] = t.split(":").map(Number);
                    if (h * 60 + m > currentMins) {
                        return { h, m };
                    }
                }
                return null;
            }

            function formatBusPayload(departure, type, name) {
                if (!departure) return null;
                const { h, m } = departure;
                const period = h >= 12 ? "pm" : "am";
                const displayHours = h % 12 === 0 ? 12 : h % 12;
                const displayMins = m.toString().padStart(2, '0');
                const timeStr = `${displayHours}:${displayMins}${period}`;

                if (type === "m10a") {
                    return {
                        icon: "\u{1F496}",
                        text: isMs ? `Bas M10A Seterusnya: ${timeStr}` : `Next M10A Bus at ${timeStr}`,
                        badge: isMs ? "Bas Pink" : "Pink Bus",
                        badgeBg: "rgba(231, 78, 159, 0.18)",
                        badgeColor: "#ff66b2"
                    };
                }

                return {
                    icon: "\u{1F68C}",
                    text: isMs ? `Bas ${name} Seterusnya: ${timeStr}` : `Next ${name} Bus at ${timeStr}`,
                    badge: isMs ? "Bas" : "Transit",
                    badgeBg: "rgba(212, 175, 55, 0.15)",
                    badgeColor: "var(--accent-gold)"
                };
            }

            // --- CASE 1: WEEKENDS (FRIDAY, SATURDAY, SUNDAY) ---
            if (isFriSatSun) {
                // If user explicitly selected an internal campus shuttle tab and route:
                if (activeTab === "internal" && activeRoute !== "m10a") {
                    const shuttle = getRouteDetails(activeRoute, activeSem, day);
                    const nextShuttleDep = findNextDeparture(shuttle.times, nowMinutes);
                    if (nextShuttleDep) {
                        return formatBusPayload(nextShuttleDep, "shuttle", shuttle.name);
                    }
                }

                // If selected shuttle has no service on weekend or has finished for the day, or by default:
                // Fallback to the next Pink Bus (M10A):
                const pinkBus = getRouteDetails("m10a", activeSem, day);
                const nextPinkDep = findNextDeparture(pinkBus.times, nowMinutes);
                if (nextPinkDep) {
                    return formatBusPayload(nextPinkDep, "m10a", "M10A");
                }

                // Blackout once all buses for the day have finished
                return null;
            }

            // --- CASE 2: WEEKDAYS (MONDAY THROUGH THURSDAY, EXCLUDING FRIDAY) ---
            // Pink buses are not available to campus on weekdays; default to KI bus
            let routeToQuery = activeRoute;
            if (activeTab === "public" || activeRoute === "m10a") {
                routeToQuery = "ki";
            }

            const primaryShuttle = getRouteDetails(routeToQuery, activeSem, day);
            const nextDep = findNextDeparture(primaryShuttle.times, nowMinutes);
            if (nextDep) {
                return formatBusPayload(nextDep, "shuttle", primaryShuttle.name);
            }

            // If selected shuttle has finished for the day, check if KI still has remaining buses
            if (routeToQuery !== "ki") {
                const kiShuttle = getRouteDetails("ki", activeSem, day);
                const nextKiDep = findNextDeparture(kiShuttle.times, nowMinutes);
                if (nextKiDep) {
                    return formatBusPayload(nextKiDep, "shuttle", "KI");
                }
            }

            // Blackout once campus shuttle buses are done for the day
            return null;
        }

        let currentSlide = 0; // 0 = weather, 1 = bus

        function updatePillGlow(targetData) {
            if (!weatherPill) return;
            weatherPill.classList.remove("glow-weather", "glow-m10a", "glow-transit");
            if (currentSlide === 0) {
                weatherPill.classList.add("glow-weather");
            } else if (targetData && targetData.badge && (targetData.badge === "Pink Bus" || targetData.badge === "Bas Pink")) {
                weatherPill.classList.add("glow-m10a");
            } else {
                weatherPill.classList.add("glow-transit");
            }
        }

        // Apply initial glow theme
        updatePillGlow(liveWeatherData);

        function updateTicker() {
            const nextBus = getNextImminentBus();

            // If no imminent bus, stay on weather
            if (!nextBus) {
                if (currentSlide !== 0) {
                    currentSlide = 0;
                    applySlide(liveWeatherData);
                    updatePillGlow(liveWeatherData);
                }
                weatherPill.style.cursor = "default";
                weatherPill.onclick = null;
                return;
            }

            // Toggle slide
            currentSlide = currentSlide === 0 ? 1 : 0;
            const targetData = currentSlide === 0 ? liveWeatherData : nextBus;

            if (tickerSlide) {
                tickerSlide.style.opacity = "0";
                tickerSlide.style.transform = "translateY(-3px)";
                weatherPill.classList.add("pill-slide-flash");
                setTimeout(() => {
                    applySlide(targetData);
                    updatePillGlow(targetData);
                    tickerSlide.style.opacity = "1";
                    tickerSlide.style.transform = "translateY(0)";
                    setTimeout(() => {
                        weatherPill.classList.remove("pill-slide-flash");
                    }, 250);
                }, 300);
            } else {
                applySlide(targetData);
                updatePillGlow(targetData);
            }

            if (currentSlide === 1) {
                weatherPill.style.cursor = "pointer";
                weatherPill.onclick = () => { window.location.href = "bus.html"; };
                weatherPill.title = "View UTeM Bus Schedules";
            } else {
                weatherPill.style.cursor = "default";
                weatherPill.onclick = null;
                weatherPill.removeAttribute("title");
            }
        }

        function applySlide(data) {
            if (weatherIcon) weatherIcon.textContent = data.icon;
            if (weatherText) weatherText.textContent = data.text;
            if (weatherBadge) {
                weatherBadge.textContent = data.badge;
                weatherBadge.style.background = data.badgeBg;
                weatherBadge.style.color = data.badgeColor;
            }
        }

        // Run ticker every 3.5s if there is an oncoming bus
        setInterval(updateTicker, 3500);
    }

    initCampusTicker();

    // Register PWA Service Worker for offline availability
    if ('serviceWorker' in navigator) {
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('./sw.js').catch(err => {
                console.log('ServiceWorker registration failed: ', err);
            });
        });
    }
});
